/// <summary>
/// CB625_TMSSOPickingListExtraction, Sales order extraction
/// </summary>
internal final class METTMSEngineSalesOrderProccess_PickingList extends METTMSEngineSalesOrderProccess
{
    boolean     isInternalCrossDockOrder;
    boolean     isCSDWarehouse;
    WMSPickingRouteID   pickingRouteId;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_salesOrderShipmentLoadHeader">SO finalisation shipment load header</param>
/// <param name = "_packingSlipId">Delivery note number</param>
public void new(SalesTable _salesTable, WMSPickingRouteID _pickingRouteId = '')
{
    // Generated pickingListId
    pickingRouteId = pickingRouteId;
}

/// <summary>
/// Validate method for execution
/// </summary>
/// <returns>true if valdidation successful; otherwise, false.</returns>
protected boolean validate()
{
    boolean ret = super();
    return ret;
}

/// <summary>
/// initialize default parameters
/// </summary>
/// <param name = "_salesTable">SalesTable record</param>
protected void init(SalesTable    _salesTable)
{
    isInternalCrossDockOrder    = metSalesTable.InternalCrossDockOrder;
    isCSDWarehouse  = inventLocation.METCSDWarehouse;
}

/// <summary>
/// return quantity for execution process
/// </summary>
/// <param name = "_salesLine"></param>
/// <returns></returns>
Qty lineShipQty(SalesLine   _salesLine)
{
    if (isInternalCrossDockOrder || isCSDWarehouse)
    {
        return _salesLine.SalesQty
            - _salesLine.pickedInTotalSalesUnit()
            - _salesLine.deliveredInTotal();
    }
    else
    //if (!isInternalCrossDockOrder && !isCSDWarehouse) 
    {
        return _salesLine.pickedInTotalSalesUnit();
    }
    //else
    //wmsTrans
}

/// <summary>
/// Retrieve the METTMSShipmentOrderTable record based on the TMS engine delivery note posting logic
/// </summary>
/// <param name = "_salesId">Sales order number</param>
/// <param name = "_pickingRouteId">Picking list number</param>
/// <returns><c>METTMSShipmentOrderTable</c> record found or empty.</returns>
protected METTMSShipmentOrderTable getTMSShipmentOrderTable(SalesIdBase _salesId, WMSPickingRouteID _pickingRouteId = '')
{
    METTMSShipmentOrderTable TMSShipmentOrderTable;

    // check to see if there is a TSO with Order number = SalesOrderID, and Pick List ID = PickListID that this order is being added to
    TMSShipmentOrderTable = super(_salesId, pickingRouteId);

    return TMSShipmentOrderTable;
}

/// <summary>
/// Method to set the fields for <c>METTMSShipmentOrderTable</c> record
/// </summary>
/// <param name = "_tmsShipmentOrderTable"><c>METTMSShipmentOrderTable</c> record</param>
protected void setTMSShipmentOrderFields(METTMSShipmentOrderTable _tmsShipmentOrderTable)
{
    super(_tmsShipmentOrderTable);

    // Step 3d: Create TSO record
    // As this is an order not processed by “TMS Engine” in past, create a TSO record to capture details of this order similar to
    // what was defined in “Step 3d” of the CB624 FSD, with the following differences an extra Pick List ID field as defined in the table below.
    _tmsShipmentOrderTable.PickListId = pickingRouteId;

}
